// Shapes mirroring `server`'s ownership-transfer endpoints (HU #10, see
// specs/023-transfer-ownership-ui/contracts/ownership-transfer-api.md),
// relayed by the gateway. camelCase like every other `server` payload.

export type OwnershipTransferStatus = 'PENDING' | 'ACCEPTED' | 'REJECTED' | 'CANCELLED';

// What POST /servers/{id}/transfers answers (201) and what accept/reject
// answer once they resolve it (200): the transfer as the backend stores it.
export type OwnershipTransfer = {
  id: string;
  serverId: string;
  currentOwnerId: string;
  targetUserId: string;
  status: OwnershipTransferStatus;
  createdAt: string;
};

// The pending transfer as GET /servers embeds it in each server. It is the
// only way to discover one — there is no listing endpoint — and `server` only
// fills it in for its two parties: the owner who started it and its target.
export type PendingOwnershipTransfer = {
  id: string;
  initiatedBy: string;
  targetUserId: string;
  createdAt: string;
};
TS_EOF
