import { apiFetch } from './apifetch';
import type { OwnershipTransfer } from './transfersTypes';

// Offers a server's ownership to one of its members (HU #10). Only the current
// owner may start it (403 otherwise), the target has to be a member and not the
// owner (400), and starting a new one cancels the previous pending transfer.
// Failures are thrown as ApiError; see initiateTransferError in
// serversErrors.ts for the user-facing text.
export async function initiateTransfer(
  serverId: string,
  targetUserId: string,
): Promise<OwnershipTransfer> {
  const response = await apiFetch(`/servers/${serverId}/transfers`, {
    method: 'POST',
    body: JSON.stringify({ targetUserId }),
  });
  return response.json();
}
TS_EOF
