import { apiFetch } from './apifetch';
import type { OwnershipTransfer } from './transfersTypes';

// Accepts an ownership transfer (HU #10), which makes the caller the server's
// new owner. Only the target may answer (403); a transfer that is no longer
// pending is a 400 — the caller reloads its list. See transferResponseError in
// serversErrors.ts for the user-facing text.
export async function acceptTransfer(
  serverId: string,
  transferId: string,
): Promise<OwnershipTransfer> {
  const response = await apiFetch(`/servers/${serverId}/transfers/${transferId}/accept`, {
    method: 'POST',
  });
  return response.json();
}
TS_EOF
