import { apiFetch } from './apifetch';
import type { OwnershipTransfer } from './transfersTypes';

// Declines an ownership transfer (HU #10): the server stays with its owner and
// nothing else changes. Only the target may answer (403); a transfer that is no
// longer pending is a 400 — the caller reloads its list. See
