import type { PendingOwnershipTransfer, ServerSummary } from '@/core/api/serversTypes';

// Pure decisions for the ownership transfers of HU #10, kept out of the views
// (same rule as membership.ts/sync.ts): the screens only render what these
// helpers select.

export type TransferDirection = 'incoming' | 'outgoing';

// A pending transfer is mine to answer when I am its target; otherwise the only
// party that can see it is the owner who started it.
export function directionOf(
  transfer: PendingOwnershipTransfer,
  userId: string,
): TransferDirection {
  return transfer.targetUserId === userId ? 'incoming' : 'outgoing';
}

// `userId` unknown (session still restoring) means no transfer is claimed: the
// client never shows an affordance it can't attribute — fail closed.
export function incomingTransferOf(
  server: ServerSummary,
  userId: string | null,
): PendingOwnershipTransfer | null {
  if (!userId) {
    return null;
  }
  const transfer = server.ownershipTransfer ?? null;
  if (!transfer) {
    return null;
  }
  return directionOf(transfer, userId) === 'incoming' ? transfer : null;
}

export function outgoingTransferOf(
  server: ServerSummary,
  userId: string | null,
): PendingOwnershipTransfer | null {
  if (!userId) {
    return null;
  }
  const transfer = server.ownershipTransfer ?? null;
  if (!transfer) {
    return null;
  }
  return directionOf(transfer, userId) === 'outgoing' ? transfer : null;
}

// Every server offering its ownership to the caller, in list order: one banner
// each, rendered above the home layout.
export function incomingTransfers(
  list: ServerSummary[] | null,
  userId: string | null,
): { server: ServerSummary; transfer: PendingOwnershipTransfer }[] {
  if (!userId) {
    return [];
  }
  const found: { server: ServerSummary; transfer: PendingOwnershipTransfer }[] = [];
  for (const server of list ?? []) {
    const transfer = incomingTransferOf(server, userId);
    if (transfer) {
      found.push({ server, transfer });
    }
  }
  return found;
}
TS_EOF
