import { useEffect, useState } from 'react';
import { View } from 'react-native';
import { HelperText, Text } from 'react-native-paper';

import { acceptTransfer } from '@/core/api/acceptTransfer';
import { rejectTransfer } from '@/core/api/rejectTransfer';
import { transferResponseError } from '@/core/api/serversErrors';
import type { PendingOwnershipTransfer, ServerSummary } from '@/core/api/serversTypes';
import { resolveProfileName } from '@/core/profile/resolveProfileName';
import ActionButton from '@/components/ActionButton';
import { colors } from '@/styles/app';
import { styles } from '@/styles/transfers';

export type TransferOutcome = 'accepted' | 'rejected';

type Props = {
  server: Pick<ServerSummary, 'id' | 'name'>;
  transfer: PendingOwnershipTransfer;
  onResolved: (outcome: TransferOutcome) => void;
};

// Persistent offer (HU #10): a Snackbar would disappear before the target could
// act on it, so the request stays on screen until it is answered. Accepting or
// rejecting goes through the REST endpoints; the page re-reads the servers
// afterwards, which is what finally removes the banner for good.
export default function OwnershipTransferBanner({ server, transfer, onResolved }: Props) {
  const [busy, setBusy] = useState<TransferOutcome | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [senderName, setSenderName] = useState<string | null>(null);

  // The owner's name is cosmetic: the banner renders right away with a generic
  // subject and updates when the shared resolver answers — it never blocks the
  // render, and a failed lookup simply keeps the generic copy.
  useEffect(() => {
    let cancelled = false;
    void resolveProfileName(transfer.initiatedBy).then((result) => {
      if (!cancelled && result.status === 'found') {
        setSenderName(result.name);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [transfer.initiatedBy]);

  async function respond(outcome: TransferOutcome) {
    setError(null);
    setBusy(outcome);
    try {
      if (outcome === 'accepted') {
        await acceptTransfer(server.id, transfer.id);
      } else {
        await rejectTransfer(server.id, transfer.id);
      }
      onResolved(outcome);
    } catch (cause) {
      // Inline, next to the buttons: the offer is still pending, so the target
      // has to be able to try again or reload without the banner vanishing.
      setError(transferResponseError(cause));
    } finally {
      setBusy(null);
    }
  }

  return (
    <View style={styles.banner} testID={`ownership-transfer-${transfer.id}`}>
      <View style={styles.bannerBody}>
        <Text style={styles.bannerTitle}>Transferencia de propiedad</Text>
        <Text style={styles.bannerText}>
          {senderName ?? 'Alguien'} te ofreció la propiedad de «{server.name}».
        </Text>
      </View>

      <View style={styles.bannerActions}>
        <ActionButton
          label={busy === 'accepted' ? 'Aceptando...' : 'Aceptar'}
          accessibilityLabel="Aceptar transferencia"
          testID="accept-transfer-button"
          style={styles.bannerButton}
          disabled={busy !== null}
          onPress={() => void respond('accepted')}
        />
        <ActionButton
          label={busy === 'rejected' ? 'Rechazando...' : 'Rechazar'}
          accessibilityLabel="Rechazar transferencia"
          testID="reject-transfer-button"
          style={styles.bannerButton}
          buttonColor={colors.secondary}
          disabled={busy !== null}
          onPress={() => void respond('rejected')}
        />
      </View>

      {error ? (
        <View style={styles.bannerError}>
          <HelperText type="error" visible>
            {error}
          </HelperText>
        </View>
      ) : null}
    </View>
  );
}
TSX_EOF
