package discordia.core.gateway;

import discordia.core.usecase.dto.OwnershipTransfer;
import discordia.core.usecase.dto.OwnershipTransferStatus;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

/**
 * Persistencia de las transferencias de propiedad (HU #10).
 *
 * <p>El único estado abierto es {@code PENDING}: las transiciones se hacen con
 * {@link #resolve} y no con un {@code updateStatus} a ciegas, para que aceptar y
 * rechazar en simultáneo no puedan ganar los dos.
 */
public interface OwnershipTransferRepository {

    OwnershipTransfer save(OwnershipTransfer transfer);

    Optional<OwnershipTransfer> findById(UUID id);

    void updateStatus(UUID id, OwnershipTransferStatus status);

    List<OwnershipTransfer> findByServerId(UUID serverId);

    /**
     * Transferencias {@code PENDING} en las que participa el usuario, ya sea como
     * dueño que la inició ({@code currentOwnerId}) o como destinatario
     * ({@code targetUserId}). Es la consulta que proyecta la pendiente en
     * {@code GET /servers}.
     */
    List<OwnershipTransfer> findPendingInvolving(String userId);

    /**
     * Cancela todas las transferencias {@code PENDING} del servidor y devuelve la
     * cantidad de filas afectadas. Se llama antes de crear una nueva para que un
     * servidor tenga como máximo una pendiente (supracesión acordada: no hay
     * endpoint de cancelar).
     */
    int cancelPendingByServerId(UUID serverId);

    /**
     * Transición condicional de estado: mueve la fila de {@code from} a {@code to}
     * y devuelve {@code true} sólo si afectó una fila.
     *
     * <p>Es condicional a propósito: el caso de uso lee la transferencia, valida
     * que esté {@code PENDING} y recién después la resuelve; sin el {@code WHERE
     * status = :from} dos requests concurrentes (accept contra reject, o dos
     * accept) pasarían las dos validaciones y ambas escribirían la propiedad del
     * servidor. La que pierde recibe {@code false} y responde 400.
     */
    boolean resolve(UUID id, OwnershipTransferStatus from, OwnershipTransferStatus to);
}
