package discordia.infra.repository;

import discordia.core.gateway.OwnershipTransferRepository;
import discordia.core.usecase.dto.OwnershipTransfer;
import discordia.core.usecase.dto.OwnershipTransferStatus;
import discordia.infra.repository.dto.OwnershipTransferEntity;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

@ApplicationScoped
public class OwnershipTransferRepositoryImpl implements OwnershipTransferRepository {

    @Inject
    OwnershipTransferPanacheRepository panache;

    @Override
    public OwnershipTransfer save(OwnershipTransfer transfer) {
        OwnershipTransferEntity entity = new OwnershipTransferEntity();
        entity.id = transfer.id();
        entity.serverId = transfer.serverId();
        entity.currentOwnerId = transfer.currentOwnerId();
        entity.targetUserId = transfer.targetUserId();
        entity.status = transfer.status();
        entity.createdAt = transfer.createdAt();
        panache.persist(entity);
        panache.flush();
        return transfer;
    }

    @Override
    public Optional<OwnershipTransfer> findById(UUID id) {
        return panache.findByIdOptional(id).map(this::wrapIntoUseCaseDto);
    }

    @Override
    public void updateStatus(UUID id, OwnershipTransferStatus status) {
        panache.update("status = ?1 where id = ?2", status, id);
    }

    @Override
    public List<OwnershipTransfer> findByServerId(UUID serverId) {
        return panache.list("serverId", serverId).stream().map(this::wrapIntoUseCaseDto).toList();
    }

    @Override
    public List<OwnershipTransfer> findPendingInvolving(String userId) {
        return panache.list(
                        "status = ?1 and (targetUserId = ?2 or currentOwnerId = ?2)",
                        OwnershipTransferStatus.PENDING,
                        userId)
                .stream()
                .map(this::wrapIntoUseCaseDto)
                .toList();
    }

    @Override
    public int cancelPendingByServerId(UUID serverId) {
        return panache.update(
                "status = ?1 where serverId = ?2 and status = ?3",
                OwnershipTransferStatus.CANCELLED,
                serverId,
                OwnershipTransferStatus.PENDING);
    }

    @Override
    public boolean resolve(UUID id, OwnershipTransferStatus from, OwnershipTransferStatus to) {
        // Un solo UPDATE condicional: las filas afectadas son la prueba de que
        // esta request fue la que resolvió la transferencia.
        return panache.update("status = ?1 where id = ?2 and status = ?3", to, id, from) == 1;
    }

    private OwnershipTransfer wrapIntoUseCaseDto(OwnershipTransferEntity entity) {
        return new OwnershipTransfer(
                entity.id,
                entity.serverId,
                entity.currentOwnerId,
                entity.targetUserId,
                entity.status,
                entity.createdAt
        );
    }
}
EOF
