package discordia.core.usecase;

import discordia.core.gateway.OwnershipTransferRepository;
import discordia.core.gateway.ServerMemberRepository;
import discordia.core.gateway.ServerRepository;
import discordia.core.usecase.dto.OwnershipTransfer;
import discordia.core.usecase.dto.OwnershipTransferStatus;
import discordia.core.usecase.dto.Server;
import discordia.core.usecase.exception.ForbiddenServerActionException;
import discordia.core.usecase.exception.NonMemberTransferException;
import discordia.core.usecase.exception.ServerNotFoundException;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import jakarta.transaction.Transactional;
import java.time.OffsetDateTime;
import java.util.UUID;

/**
 * HU #10, CA 1 y CA 2: el dueño inicia la transferencia hacia otro miembro.
 *
 * <p>Orden de chequeos del contrato: {@code 404} servidor inexistente → {@code 403}
 * caller que no es el dueño → {@code 400} destinatario vacío, el propio dueño o
 * alguien que no es miembro.
 *
 * <p>El servidor se carga con {@link ServerRepository#lockById}: el lock pesimista
 * serializa esta escritura con {@code DeleteServer} y con otra iniciación del
 * mismo servidor, así que la cancelación de la pendiente anterior y el alta de la
 * nueva ocurren sobre el mismo estado.
 *
 * <p><strong>Una sola pendiente por servidor (supracesión).</strong> No hay endpoint
 * de cancelar: iniciar una transferencia nueva cancela las pendientes anteriores
 * ({@code CANCELLED}), de modo que el cliente nunca tiene que elegir entre dos
 * solicitudes vivas del mismo servidor.
 */
@ApplicationScoped
public class InitiateOwnershipTransfer {

    private final ServerRepository serverRepository;
    private final ServerMemberRepository serverMemberRepository;
    private final OwnershipTransferRepository ownershipTransferRepository;

    @Inject
    public InitiateOwnershipTransfer(
            ServerRepository serverRepository,
            ServerMemberRepository serverMemberRepository,
            OwnershipTransferRepository ownershipTransferRepository
    ) {
        this.serverRepository = serverRepository;
        this.serverMemberRepository = serverMemberRepository;
        this.ownershipTransferRepository = ownershipTransferRepository;
    }

    @Transactional
    public OwnershipTransfer execute(UUID serverId, String requesterId, String targetUserId) {
        if (requesterId == null || requesterId.trim().isEmpty()) {
            throw new ForbiddenServerActionException("User identity is required");
        }

        String trimmedRequester = requesterId.trim();

        Server server = serverRepository.lockById(serverId)
                .orElseThrow(() -> new ServerNotFoundException(serverId));

        if (!trimmedRequester.equals(server.ownerId())) {
            throw new ForbiddenServerActionException("Only the server owner can initiate ownership transfer");
        }

        if (targetUserId == null || targetUserId.trim().isEmpty()) {
            throw new NonMemberTransferException("Target user must be specified");
        }

        String trimmedTarget = targetUserId.trim();

        if (trimmedTarget.equals(server.ownerId())) {
            throw new NonMemberTransferException("Cannot transfer ownership to yourself");
        }

        if (!serverMemberRepository.existsByServerIdAndUserId(serverId, trimmedTarget)) {
            throw new NonMemberTransferException("Target user is not a member of the server");
        }

        // Supracesión: como máximo una PENDING por servidor.
        ownershipTransferRepository.cancelPendingByServerId(serverId);

        OwnershipTransfer transfer = new OwnershipTransfer(
                UUID.randomUUID(),
                serverId,
                trimmedRequester,
                trimmedTarget,
                OwnershipTransferStatus.PENDING,
                OffsetDateTime.now()
        );

        return ownershipTransferRepository.save(transfer);
    }
}
EOF
