package discordia.core.usecase;

import discordia.core.gateway.OwnershipTransferRepository;
import discordia.core.gateway.ServerMemberRepository;
import discordia.core.gateway.ServerRepository;
import discordia.core.usecase.dto.OwnershipTransfer;
import discordia.core.usecase.dto.OwnershipTransferStatus;
import discordia.core.usecase.dto.Server;
import discordia.core.usecase.dto.ServerMember;
import discordia.core.usecase.exception.ForbiddenServerActionException;
import discordia.core.usecase.exception.InvalidTransferStateException;
import discordia.core.usecase.exception.NonMemberTransferException;
import discordia.core.usecase.exception.ServerNotFoundException;
import discordia.core.usecase.exception.TransferNotFoundException;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import jakarta.transaction.Transactional;
import java.time.OffsetDateTime;
import java.util.UUID;

/**
 * HU #10, CA 1: el destinatario acepta y pasa a ser el dueño; el dueño anterior
 * queda como miembro regular.
 *
 * <p>La transacción corre con el servidor bloqueado
 * ({@link ServerRepository#lockById}): el lock serializa con {@code DeleteServer} y
 * con otra aceptación o rechazo del mismo servidor, así que todas las validaciones
 * y las escrituras ven el mismo estado.
 *
 * <p>Orden de chequeos del contrato: {@code 404} servidor inexistente → {@code 404}
 * transferencia inexistente (o de otro servidor) → {@code 403} caller que no es el
 * destinatario → {@code 400} transferencia ya resuelta, transferencia vieja o
 * destinatario que dejó de ser miembro.
 *
 * <p><strong>Resolución condicional.</strong> La transferencia se pasa a
 * {@code ACCEPTED} con {@link OwnershipTransferRepository#resolve} antes de tocar
 * la propiedad: si otra request concurrente ya la resolvió, este caso de uso
 * aborta con {@code 400} en lugar de sobrescribir al dueño. Recién después se
 * actualiza {@code servers.owner_id}.
 *
 * <p><strong>Conversión del dueño anterior a miembro.</strong> El dueño no tiene
 * fila en {@code server_members} (la propiedad es implícita: la resuelve
 * {@link ResolveMemberPermissions} comparando {@code servers.owner_id}), así que al
 * transferir hay que materializarlo como miembro regular. Se usa
 * {@link ServerMemberRepository#insertIfAbsent} y no {@code exists} + {@code save}:
 * la unicidad {@code (server_id, user_id)} la garantiza la base y un alta
 * concurrente es un resultado normal (vacío), nunca una violación de PK.
 *
 * <p>No se copian roles del dueño ni se inserta nada en {@code server_member_roles}:
 * el baseline de todo miembro es {@link RolePermissions#DEFAULT}
 * ({@code VIEW_CHANNELS | SEND_MESSAGES}), que es exactamente lo que resuelve
 * {@link ResolveMemberPermissions} para un miembro sin roles. Copiar los roles —o
 * heredar el {@code ALL} implícito del dueño— le dejaría capacidades de
 * administración que ya no le corresponden; para recuperarlas, el nuevo dueño debe
 * asignarle un rol explícito (por ejemplo con {@code ADMINISTRATOR}).
 */
@ApplicationScoped
public class AcceptOwnershipTransfer {

    private final ServerRepository serverRepository;
    private final ServerMemberRepository serverMemberRepository;
    private final OwnershipTransferRepository ownershipTransferRepository;

    @Inject
    public AcceptOwnershipTransfer(
            ServerRepository serverRepository,
            ServerMemberRepository serverMemberRepository,
            OwnershipTransferRepository ownershipTransferRepository
    ) {
        this.serverRepository = serverRepository;
        this.serverMemberRepository = serverMemberRepository;
        this.ownershipTransferRepository = ownershipTransferRepository;
    }

    @Transactional
    public OwnershipTransfer execute(UUID serverId, UUID transferId, String requesterId) {
        if (requesterId == null || requesterId.trim().isEmpty()) {
            throw new ForbiddenServerActionException("User identity is required");
        }

        String trimmedRequester = requesterId.trim();

        Server server = serverRepository.lockById(serverId)
                .orElseThrow(() -> new ServerNotFoundException(serverId));

        OwnershipTransfer transfer = ownershipTransferRepository.findById(transferId)
                .filter(t -> t.serverId().equals(serverId))
                .orElseThrow(() -> new TransferNotFoundException(transferId));

        if (!trimmedRequester.equals(transfer.targetUserId())) {
            throw new ForbiddenServerActionException("Only the designated target user can accept the transfer");
        }

        if (transfer.status() != OwnershipTransferStatus.PENDING) {
            throw new InvalidTransferStateException("Transfer is no longer pending");
        }

        // Consistencia: si la propiedad cambió después de iniciada la transferencia,
        // la solicitud quedó vieja y no puede aplicarse.
        if (!server.ownerId().equals(transfer.currentOwnerId())) {
            throw new InvalidTransferStateException("Transfer is stale: the server owner changed");
        }

        if (!serverMemberRepository.existsByServerIdAndUserId(serverId, transfer.targetUserId())) {
            throw new NonMemberTransferException("The target user is no longer a member of the server");
        }

        if (!ownershipTransferRepository.resolve(
                transferId, OwnershipTransferStatus.PENDING, OwnershipTransferStatus.ACCEPTED)) {
            throw new InvalidTransferStateException("Transfer is no longer pending");
        }

        serverRepository.updateOwner(serverId, transfer.targetUserId());

        serverMemberRepository.insertIfAbsent(new ServerMember(
                UUID.randomUUID(),
                serverId,
                transfer.currentOwnerId(),
                OffsetDateTime.now()
        ));

        return transfer.withStatus(OwnershipTransferStatus.ACCEPTED);
    }
}
