import { useEffect, useState } from 'react';
import { Pressable, ScrollView, View } from 'react-native';
import { ActivityIndicator, HelperText, Icon, Text } from 'react-native-paper';

import { getMembers, MEMBERS_PAGE_SIZE } from '@/core/api/getMembers';
import { initiateTransfer } from '@/core/api/initiateTransfer';
import type { ServerMember } from '@/core/api/membersTypes';
import { rolesFormError } from '@/core/api/rolesErrors';
import { initiateTransferError } from '@/core/api/serversErrors';
import type { ServerSummary } from '@/core/api/serversTypes';
import { useMemberNames } from '@/core/members/useMemberNames';
import { outgoingTransferOf } from '@/core/servers/transfers';
import ActionButton from '@/components/ActionButton';
import { colors, styles as appStyles } from '@/styles/app';
import { styles } from '@/styles/transfers';

type Props = {
  // The list entry, not GET /servers/{id}: `ownershipTransfer` only travels in
  // GET /servers (it is the single source of the pending transfer).
  server: ServerSummary;
  userId: string | null;
  onInitiated: (serverName: string) => void;
  onCancel: () => void;
};

// Owner's side of HU #10: pick one member and hand the server over. The listing
// is paginated by the backend, so the form loads a single page (same criterion
// as RoleMembers) and never asks for an unbounded collection; the owner and the
// caller are left out because the backend refuses both.
export default function TransferOwnershipForm({ server, userId, onInitiated, onCancel }: Props) {
  const [members, setMembers] = useState<ServerMember[] | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [selected, setSelected] = useState<string | null>(null);
  const [sending, setSending] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  // Bumped by Reintentar to re-run the load effect (same convention as
  // RoleMembers and pages/index.tsx).
  const [reloadToken, setReloadToken] = useState(0);
  const names = useMemberNames(members);

  useEffect(() => {
    let cancelled = false;

    async function load() {
      setLoadError(null);
      try {
        const page = await getMembers(server.id, { limit: MEMBERS_PAGE_SIZE, offset: 0 });
        if (cancelled) return;
        // Filtered before storing the page: `useMemberNames` takes the array
        // itself, so the state has to keep one stable identity (and it never
        // resolves a name it is not going to show).
        setMembers(
          page.members.filter(
            (member) => member.userId !== userId && member.userId !== server.ownerId,
          ),
        );
      } catch (cause) {
        if (!cancelled) {
          setMembers(null);
          setLoadError(rolesFormError(cause));
        }
      }
    }

    void load();
    return () => {
      cancelled = true;
    };
  }, [server.id, server.ownerId, userId, reloadToken]);

  const pendingOutgoing = outgoingTransferOf(server, userId);

  async function submit() {
    if (!selected || sending) return;
    setSubmitError(null);
    setSending(true);
    try {
      await initiateTransfer(server.id, selected);
      onInitiated(server.name);
    } catch (cause) {
      setSubmitError(initiateTransferError(cause));
    } finally {
      setSending(false);
    }
  }

  return (
    <View style={styles.container}>
      <Text variant="titleMedium" style={appStyles.formTitle}>
        Transferir «{server.name}»
      </Text>
      <Text style={styles.hint}>
        Elegí quién va a ser el nuevo dueño. Al aceptar, el servidor pasa a ser suyo y vos quedás
        como un miembro más: no se puede deshacer.
      </Text>

      {pendingOutgoing ? (
        <View style={styles.notice} testID="pending-transfer-notice">
          <Text style={styles.noticeText}>
            Ya hay una transferencia pendiente sin responder. Si iniciás otra, la anterior se
            cancela.
          </Text>
        </View>
      ) : null}

      {loadError ? (
        <View style={styles.errorBox}>
          <Text variant="bodyMedium" style={styles.mutedText}>
            {loadError}
          </Text>
          <ActionButton
            label="Reintentar"
            accessibilityLabel="Reintentar la carga de miembros"
            testID="retry-transfer-members"
            buttonColor={colors.secondary}
            onPress={() => setReloadToken((token) => token + 1)}
          />
        </View>
      ) : members === null ? (
        <ActivityIndicator style={styles.loading} />
      ) : members.length === 0 ? (
        <Text variant="bodyMedium" style={styles.mutedText}>
          Este servidor todavía no tiene otros miembros.
        </Text>
      ) : (
        <ScrollView style={styles.list}>
          {members.map((member) => {
            const name = names[member.userId] ?? member.userId;
            const isSelected = selected === member.userId;
            return (
              <Pressable
                key={member.userId}
                accessibilityRole="radio"
                accessibilityState={{ checked: isSelected }}
                accessibilityLabel={`Elegir a ${name}`}
                testID={`transfer-target-${member.userId}`}
                onPress={() => setSelected(member.userId)}
                style={[styles.memberRow, isSelected && styles.memberRowSelected]}
              >
                <View style={styles.memberBody}>
                  <Text style={styles.memberName}>{name}</Text>
                  <Text style={styles.memberMeta}>
                    {isSelected ? 'Nuevo dueño' : 'Miembro del servidor'}
                  </Text>
                </View>
                {isSelected ? <Icon source="check" size={18} color={colors.primarySoft} /> : null}
              </Pressable>
            );
          })}
        </ScrollView>
      )}

      {submitError ? (
        <HelperText type="error" visible>
          {submitError}
        </HelperText>
      ) : null}

      <ActionButton
        label={sending ? 'Transfiriendo...' : 'Transferir propiedad'}
        accessibilityLabel="Confirmar transferencia de propiedad"
        testID="confirm-transfer-button"
        disabled={!selected || sending || members === null}
        onPress={() => void submit()}
      />
      <ActionButton
        label="Cancelar"
        accessibilityLabel="Cancelar"
        testID="cancel-transfer-button"
        buttonColor={colors.secondary}
        disabled={sending}
        onPress={onCancel}
      />
    </View>
  );
}
