package discordia.core.usecase;

import discordia.core.gateway.OwnershipTransferRepository;
import discordia.core.usecase.dto.OwnershipTransfer;
import discordia.core.usecase.dto.OwnershipTransferStatus;
import discordia.core.usecase.exception.ForbiddenServerActionException;
import discordia.core.usecase.exception.InvalidTransferStateException;
import discordia.core.usecase.exception.TransferNotFoundException;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import jakarta.transaction.Transactional;
import java.util.UUID;

/**
 * HU #10, CA 3: el destinatario rechaza y la propiedad no cambia.
 *
 * <p>Orden de chequeos del contrato: {@code 404} transferencia inexistente (o de
 * otro servidor) → {@code 403} caller que no es el destinatario → {@code 400}
 * transferencia ya resuelta.
 *
 * <p>La resolución es condicional ({@link OwnershipTransferRepository#resolve}):
 * si una aceptación concurrente ganó el {@code UPDATE}, esta request recibe
 * {@code false} y responde {@code 400} en lugar de marcar como rechazada una
 * transferencia ya aceptada. El servidor no se toca en ningún caso (CA 3).
 */
@ApplicationScoped
public class RejectOwnershipTransfer {

    private final OwnershipTransferRepository ownershipTransferRepository;

    @Inject
    public RejectOwnershipTransfer(OwnershipTransferRepository ownershipTransferRepository) {
        this.ownershipTransferRepository = ownershipTransferRepository;
    }

    @Transactional
    public OwnershipTransfer execute(UUID serverId, UUID transferId, String requesterId) {
        if (requesterId == null || requesterId.trim().isEmpty()) {
            throw new ForbiddenServerActionException("User identity is required");
        }

        String trimmedRequester = requesterId.trim();

        OwnershipTransfer transfer = ownershipTransferRepository.findById(transferId)
                .filter(t -> t.serverId().equals(serverId))
                .orElseThrow(() -> new TransferNotFoundException(transferId));

        if (!trimmedRequester.equals(transfer.targetUserId())) {
            throw new ForbiddenServerActionException("Only the designated target user can reject the transfer");
        }

        if (transfer.status() != OwnershipTransferStatus.PENDING) {
            throw new InvalidTransferStateException("Transfer is no longer pending");
        }

        if (!ownershipTransferRepository.resolve(
                transferId, OwnershipTransferStatus.PENDING, OwnershipTransferStatus.REJECTED)) {
            throw new InvalidTransferStateException("Transfer is no longer pending");
        }

        return transfer.withStatus(OwnershipTransferStatus.REJECTED);
    }
}
