package discordia.core.usecase;

import discordia.core.gateway.OwnershipTransferRepository;
import discordia.core.gateway.ServerRepository;
import discordia.core.usecase.dto.OwnershipTransfer;
import discordia.core.usecase.dto.OwnershipTransferStatus;
import discordia.core.usecase.dto.ServerAccess;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

@ApplicationScoped
public class ListServers {

    private final ServerRepository serverRepository;
    private final OwnershipTransferRepository ownershipTransferRepository;

    @Inject
    public ListServers(ServerRepository serverRepository, OwnershipTransferRepository ownershipTransferRepository) {
        this.serverRepository = serverRepository;
        this.ownershipTransferRepository = ownershipTransferRepository;
    }

    /**
     * Every server the user owns or joined, with the relationship (014) and, per
     * server, the pending ownership transfer the caller takes part in (HU #10).
     */
    public Result execute(String userId) {
        List<ServerAccess> servers = serverRepository.findAccessibleBy(userId);
        return new Result(servers, servers.size(), pendingTransfersByServer(userId));
    }

    /**
     * Transferencia pendiente por servidor: sólo aparece en los servidores donde el
     * caller es el iniciador o el destinatario, que son las dos únicas partes a las
     * que la transferencia les cambia algo. Una por servidor: iniciar una nueva
     * cancela la anterior, y si los datos igual tuvieran dos gana la más reciente.
     */
    private Map<UUID, OwnershipTransfer> pendingTransfersByServer(String userId) {
        if (userId == null || userId.isBlank()) {
            return Map.of();
        }
        Map<UUID, OwnershipTransfer> byServer = new HashMap<>();
        for (OwnershipTransfer transfer : ownershipTransferRepository.findPendingInvolving(userId.trim())) {
            if (transfer.status() != OwnershipTransferStatus.PENDING) {
                continue;
            }
            byServer.merge(transfer.serverId(), transfer, ListServers::newest);
        }
        return Map.copyOf(byServer);
    }

    private static OwnershipTransfer newest(OwnershipTransfer current, OwnershipTransfer candidate) {
        return candidate.createdAt().isAfter(current.createdAt()) ? candidate : current;
    }

    public record Result(
            List<ServerAccess> servers, long count, Map<UUID, OwnershipTransfer> pendingTransfersByServer) {
    }
}
