package discordia.controller.contract;

import discordia.core.usecase.dto.OwnershipTransfer;
import discordia.core.usecase.dto.ServerAccess;
import java.time.OffsetDateTime;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.UUID;

public record ServerListResponse(long count, List<Summary> servers) {

    public static ServerListResponse from(
            List<ServerAccess> servers, long count, Map<UUID, OwnershipTransfer> pendingTransfersByServer) {
        return new ServerListResponse(
                count,
                servers.stream()
                        .map(access -> Summary.from(access, pendingTransfersByServer.get(access.server().id())))
                        .toList());
    }

    /**
     * {@code relationship} es {@code "owner"} o {@code "member"} (014) y
     * {@code ownershipTransfer} es la transferencia pendiente que involucra al caller,
     * o {@code null} cuando no participa (HU #10: el cliente no consulta un endpoint
     * aparte para saber si hay una solicitud viva).
     */
    public record Summary(
            UUID id,
            String ownerId,
            String name,
            OffsetDateTime createdAt,
            String relationship,
            PendingTransfer ownershipTransfer) {

        public static Summary from(ServerAccess access, OwnershipTransfer pendingTransfer) {
            var server = access.server();
            return new Summary(
                    server.id(),
                    server.ownerId(),
                    server.name(),
                    server.createdAt(),
                    access.relationship().name().toLowerCase(Locale.ROOT),
                    pendingTransfer == null ? null : PendingTransfer.from(pendingTransfer));
        }
    }

    /**
     * Vista mínima de la transferencia pendiente: {@code initiatedBy} es el dueño que
     * la inició ({@code currentOwnerId}) y el destinatario sólo necesita el id para
     * aceptar o rechazar.
     */
    public record PendingTransfer(UUID id, String initiatedBy, String targetUserId, OffsetDateTime createdAt) {

        public static PendingTransfer from(OwnershipTransfer transfer) {
            return new PendingTransfer(
                    transfer.id(),
                    transfer.currentOwnerId(),
                    transfer.targetUserId(),
                    transfer.createdAt());
        }
    }
}
