import java.util.List;
import java.util.Optional;
import java.util.UUID;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class TransferOwnershipTest {

    private FakeServerRepository serverRepository;
    private FakeServerMemberRepository memberRepository;
    private FakeOwnershipTransferRepository transferRepository;

    private InitiateOwnershipTransfer initiateTransfer;
    private AcceptOwnershipTransfer acceptTransfer;
    private RejectOwnershipTransfer rejectTransfer;

    private Server sampleServer;
    private final String ownerId = "owner-100";
    private final String memberId = "member-200";
    private final String strangerId = "stranger-300";

    @BeforeEach
    void setUp() {
        serverRepository = new FakeServerRepository();
        memberRepository = new FakeServerMemberRepository();
        transferRepository = new FakeOwnershipTransferRepository();

        initiateTransfer = new InitiateOwnershipTransfer(serverRepository, memberRepository, transferRepository);
        acceptTransfer = new AcceptOwnershipTransfer(serverRepository, memberRepository, transferRepository);
        rejectTransfer = new RejectOwnershipTransfer(transferRepository);

        sampleServer = new Server(UUID.randomUUID(), ownerId, "Awesome Server", OffsetDateTime.now());
        serverRepository.save(sampleServer);

        // owner y member están en server_members
        memberRepository.save(new ServerMember(UUID.randomUUID(), sampleServer.id(), ownerId, OffsetDateTime.now()));
        memberRepository.save(new ServerMember(UUID.randomUUID(), sampleServer.id(), memberId, OffsetDateTime.now()));
    }

    // --- CA 1: iniciación y aceptación --------------------------------------

    @Test
    void initiateTransfer_withValidMember_createsPendingTransfer() {
        OwnershipTransfer transfer = initiateTransfer.execute(sampleServer.id(), ownerId, memberId);

        assertNotNull(transfer.id());
        assertEquals(sampleServer.id(), transfer.serverId());
        assertEquals(ownerId, transfer.currentOwnerId());
        assertEquals(memberId, transfer.targetUserId());
        assertEquals(OwnershipTransferStatus.PENDING, transfer.status());
    }

    @Test
    void initiateTransfer_whenServerDoesNotExist_throwsServerNotFoundException() {
        UUID unknownServerId = UUID.randomUUID();

        assertThrows(
                ServerNotFoundException.class,
                () -> initiateTransfer.execute(unknownServerId, ownerId, memberId));
        assertTrue(transferRepository.saved.isEmpty());
    }

    @Test
    void acceptTransfer_byTargetMember_updatesServerOwnerAndKeepsOldOwnerAsMember() {
        OwnershipTransfer transfer = initiateTransfer.execute(sampleServer.id(), ownerId, memberId);

        OwnershipTransfer accepted = acceptTransfer.execute(sampleServer.id(), transfer.id(), memberId);

        assertEquals(OwnershipTransferStatus.ACCEPTED, accepted.status());
        assertEquals(OwnershipTransferStatus.ACCEPTED, transferRepository.stored(transfer.id()).orElseThrow().status());
        Server updatedServer = serverRepository.findById(sampleServer.id()).orElseThrow();
        assertEquals(memberId, updatedServer.ownerId());
        assertTrue(memberRepository.existsByServerIdAndUserId(sampleServer.id(), ownerId));
    }

    @Test
    void acceptTransfer_byUnauthorizedUser_throwsForbiddenServerActionException() {
        OwnershipTransfer transfer = initiateTransfer.execute(sampleServer.id(), ownerId, memberId);

        assertThrows(
                ForbiddenServerActionException.class,
                () -> acceptTransfer.execute(sampleServer.id(), transfer.id(), strangerId));
        assertEquals(ownerId, serverRepository.findById(sampleServer.id()).orElseThrow().ownerId());
        assertEquals(OwnershipTransferStatus.PENDING, transferRepository.stored(transfer.id()).orElseThrow().status());
    }

    @Test
    void acceptTransfer_alreadyResolved_throwsInvalidTransferStateException() {
        OwnershipTransfer transfer = initiateTransfer.execute(sampleServer.id(), ownerId, memberId);
        acceptTransfer.execute(sampleServer.id(), transfer.id(), memberId);

        assertThrows(
                InvalidTransferStateException.class,
                () -> acceptTransfer.execute(sampleServer.id(), transfer.id(), memberId));
    }

    @Test
    void acceptTransfer_whenServerDoesNotExist_throwsServerNotFoundException() {
        OwnershipTransfer transfer = initiateTransfer.execute(sampleServer.id(), ownerId, memberId);
        UUID unknownServerId = UUID.randomUUID();

        assertThrows(
                ServerNotFoundException.class,
                () -> acceptTransfer.execute(unknownServerId, transfer.id(), memberId));
