                TransferNotFoundException.class,
                () -> acceptTransfer.execute(sampleServer.id(), UUID.randomUUID(), memberId));
    }

    @Test
    void acceptTransfer_whenTargetIsNoLongerMember_throwsNonMemberTransferException() {
        OwnershipTransfer transfer = initiateTransfer.execute(sampleServer.id(), ownerId, memberId);
        memberRepository.deleteByServerIdAndUserId(sampleServer.id(), memberId);

        NonMemberTransferException ex = assertThrows(
                NonMemberTransferException.class,
                () -> acceptTransfer.execute(sampleServer.id(), transfer.id(), memberId));

        assertEquals("The target user is no longer a member of the server", ex.getMessage());
        assertEquals(ownerId, serverRepository.findById(sampleServer.id()).orElseThrow().ownerId());
