        transferRepository.resolveSucceeds = false;

        InvalidTransferStateException ex = assertThrows(
                InvalidTransferStateException.class,
                () -> acceptTransfer.execute(sampleServer.id(), transfer.id(), memberId));

        assertEquals("Transfer is no longer pending", ex.getMessage());
        // La propiedad no se toca si el UPDATE condicional no afectó la fila.
        assertEquals(ownerId, serverRepository.findById(sampleServer.id()).orElseThrow().ownerId());
        assertEquals(1, memberRepository.countByServerId(sampleServer.id()) - 1);
