    // --- Supracesión ---------------------------------------------------------

    @Test
    void initiateTransfer_twice_cancelsThePreviousPendingTransfer() {
        String otherMemberId = "member-400";
        memberRepository.save(new ServerMember(UUID.randomUUID(), sampleServer.id(), otherMemberId, OffsetDateTime.now()));

        OwnershipTransfer first = initiateTransfer.execute(sampleServer.id(), ownerId, memberId);
        OwnershipTransfer second = initiateTransfer.execute(sampleServer.id(), ownerId, otherMemberId);

        assertEquals(OwnershipTransferStatus.CANCELLED, transferRepository.stored(first.id()).orElseThrow().status());
        assertEquals(OwnershipTransferStatus.PENDING, transferRepository.stored(second.id()).orElseThrow().status());
