    private static class FakeServerRepository implements ServerRepository {
        private final List<Server> saved = new ArrayList<>();

        @Override
        public Server save(Server server) {
            saved.add(server);
            return server;
        }

        @Override
        public Optional<Server> findById(UUID id) {
            return saved.stream().filter(s -> s.id().equals(id)).findFirst();
        }

        @Override
        public List<ServerAccess> findAccessibleBy(String userId) {
            return saved.stream()
                    .filter(s -> s.ownerId().equals(userId))
                    .map(s -> new ServerAccess(s, ServerRelationship.OWNER, s.createdAt()))
                    .toList();
        }

        @Override
        public void deleteById(UUID id) {
            saved.removeIf(s -> s.id().equals(id));
        }

        @Override
        public void updateOwner(UUID id, String newOwnerId) {
            for (int i = 0; i < saved.size(); i++) {
                if (saved.get(i).id().equals(id)) {
                    Server old = saved.get(i);
                    saved.set(i, new Server(old.id(), newOwnerId, old.name(), old.createdAt()));
                    return;
                }
            }
        }
    }

    private static class FakeServerMemberRepository implements ServerMemberRepository {
        private final List<ServerMember> saved = new ArrayList<>();
        private int insertIfAbsentCalls;
        private int saveCalls;

        @Override
        public ServerMember save(ServerMember member) {
            saveCalls++;
            saved.add(member);
            return member;
        }

        @Override
        public Optional<ServerMember> insertIfAbsent(ServerMember member) {
            insertIfAbsentCalls++;
            if (existsByServerIdAndUserId(member.serverId(), member.userId())) {
                return Optional.empty();
            }
            saved.add(member);
            return Optional.of(member);
        }

        @Override
        public Optional<ServerMember> findByServerIdAndUserId(UUID serverId, String userId) {
            return saved.stream()
                    .filter(m -> m.serverId().equals(serverId) && m.userId().equals(userId))
                    .findFirst();
        }

        @Override
        public List<ServerMember> findByServerId(UUID serverId) {
            return saved.stream().filter(m -> m.serverId().equals(serverId)).toList();
        }

        @Override
        public boolean existsByServerIdAndUserId(UUID serverId, String userId) {
            return saved.stream()
                    .anyMatch(m -> m.serverId().equals(serverId) && m.userId().equals(userId));
        }

        @Override
        public void deleteByServerIdAndUserId(UUID serverId, String userId) {
            saved.removeIf(m -> m.serverId().equals(serverId) && m.userId().equals(userId));
        }

        @Override
        public void deleteByServerId(UUID serverId) {
            saved.removeIf(m -> m.serverId().equals(serverId));
        }

        long countByServerId(UUID serverId) {
            return saved.stream().filter(m -> m.serverId().equals(serverId)).count();
        }

        long countByServerIdAndUserId(UUID serverId, String userId) {
            return saved.stream()
                    .filter(m -> m.serverId().equals(serverId) && m.userId().equals(userId))
                    .count();
        }
    }

    private static class FakeOwnershipTransferRepository implements OwnershipTransferRepository {
        private final List<OwnershipTransfer> saved = new ArrayList<>();
        private boolean resolveSucceeds = true;

        @Override
        public OwnershipTransfer save(OwnershipTransfer transfer) {
            saved.add(transfer);
            return transfer;
        }

        @Override
        public Optional<OwnershipTransfer> findById(UUID id) {
            return stored(id);
        }

        @Override
        public void updateStatus(UUID id, OwnershipTransferStatus status) {
            for (int i = 0; i < saved.size(); i++) {
                if (saved.get(i).id().equals(id)) {
                    saved.set(i, saved.get(i).withStatus(status));
                    return;
                }
            }
        }

        @Override
        public List<OwnershipTransfer> findByServerId(UUID serverId) {
            return saved.stream().filter(t -> t.serverId().equals(serverId)).toList();
        }

        @Override
        public List<OwnershipTransfer> findPendingInvolving(String userId) {
            return saved.stream()
                    .filter(t -> t.status() == OwnershipTransferStatus.PENDING)
                    .filter(t -> t.targetUserId().equals(userId) || t.currentOwnerId().equals(userId))
                    .toList();
        }

        @Override
        public int cancelPendingByServerId(UUID serverId) {
            int affected = 0;
            for (int i = 0; i < saved.size(); i++) {
                OwnershipTransfer current = saved.get(i);
                if (current.serverId().equals(serverId) && current.status() == OwnershipTransferStatus.PENDING) {
                    saved.set(i, current.withStatus(OwnershipTransferStatus.CANCELLED));
                    affected++;
                }
            }
            return affected;
        }

        @Override
        public boolean resolve(UUID id, OwnershipTransferStatus from, OwnershipTransferStatus to) {
            if (!resolveSucceeds) {
                return false;
            }
            for (int i = 0; i < saved.size(); i++) {
                OwnershipTransfer current = saved.get(i);
                if (current.id().equals(id) && current.status() == from) {
                    saved.set(i, current.withStatus(to));
                    return true;
                }
            }
            return false;
        }

        Optional<OwnershipTransfer> stored(UUID id) {
            return saved.stream().filter(t -> t.id().equals(id)).findFirst();
        }

        List<OwnershipTransfer> pendingOfServer(UUID serverId) {
            return saved.stream()
                    .filter(t -> t.serverId().equals(serverId))
                    .filter(t -> t.status() == OwnershipTransferStatus.PENDING)
                    .toList();
        }
    }
}
