            UUID serverId, String currentOwnerId, String targetUserId, OwnershipTransferStatus status) {
        return new OwnershipTransfer(UUID.randomUUID(), serverId, currentOwnerId, targetUserId, status, NOW);
    }

    @Test
    void returnsTheAccessibleServersInRepositoryOrder_withTheirCount() {
        List<ServerAccess> accesses = List.of(
