        assertTrue(result.servers().isEmpty());
        assertEquals(0, result.count());
    }

    /**
     * La pendiente sólo se proyecta en el servidor del que el caller es parte (como
     * iniciador o como destinatario); los demás servidores quedan sin entrada, que es
     * lo que el contrato serializa como {@code null}.
     */
    @Test
    void projectsThePendingTransferOnlyForTheServersWhereTheCallerTakesPart() {
        ServerAccess asInitiator = access("initiated", ServerRelationship.OWNER);
        ServerAccess asTarget = access("targeted", ServerRelationship.MEMBER);
        ServerAccess notInvolved = access("unrelated", ServerRelationship.MEMBER);
        ServerAccess someoneElse = access("other-people", ServerRelationship.MEMBER);

        OwnershipTransfer initiated = transfer(
                asInitiator.server().id(), USER, OTHER, OwnershipTransferStatus.PENDING);
        OwnershipTransfer received = transfer(
                asTarget.server().id(), OTHER, USER, OwnershipTransferStatus.PENDING);
        OwnershipTransfer foreign = transfer(
                someoneElse.server().id(), OTHER, "user-3", OwnershipTransferStatus.PENDING);

        FakeTransferRepository transfers = new FakeTransferRepository();
        transfers.save(initiated);
        transfers.save(received);
        transfers.save(foreign);

        ListServers.Result result = new ListServers(
                        repositoryReturning(List.of(asInitiator, asTarget, notInvolved, someoneElse)), transfers)
                .execute(USER);

        assertEquals(2, result.pendingTransfersByServer().size());
        assertEquals(initiated, result.pendingTransfersByServer().get(asInitiator.server().id()));
        assertEquals(received, result.pendingTransfersByServer().get(asTarget.server().id()));
        assertFalse(result.pendingTransfersByServer().containsKey(notInvolved.server().id()));
        assertFalse(result.pendingTransfersByServer().containsKey(someoneElse.server().id()));
    }

    @Test
    void ignoresTransfersThatAreNoLongerPending() {
        ServerAccess owned = access("owned", ServerRelationship.OWNER);
        FakeTransferRepository transfers = new FakeTransferRepository();
        transfers.save(transfer(owned.server().id(), USER, OTHER, OwnershipTransferStatus.ACCEPTED));
        transfers.save(transfer(owned.server().id(), USER, OTHER, OwnershipTransferStatus.CANCELLED));

        ListServers.Result result = new ListServers(repositoryReturning(List.of(owned)), transfers).execute(USER);

        assertTrue(result.pendingTransfersByServer().isEmpty());
        assertNull(result.pendingTransfersByServer().get(owned.server().id()));
